SELECT 
    ST_AsGeoJSON(
        ST_ConvexHull(
            ST_Collect(ARRAY_AGG(geometry))
        )
    ) AS hull_geojson,
    ST_Area_Spheroid(
        ST_ConvexHull(
            ST_Collect(ARRAY_AGG(geometry))
        )
    ) / 1000000.0 AS area_km2
FROM eu_nuts_regions
WHERE cntr_code = 'DE' AND levl_code = 3
